def late_fee(days_late, is_member):
    if days_late < 0:
        return {'status': 'error', 'fee': 0.0}
    elif days_late <= 3:
        return {'status': 'free', 'fee': 0.0}
    else:
        fee = min(days_late - 3, 10.0) * 0.5
        if is_member:
            return {'status': 'member', 'fee': fee / 2}
        else:
            return {'status': 'non-member', 'fee': fee}

